# Let me try a smarter approach: start with known high-girth graphs and modify them
# or use a greedy construction

import networkx as nx
import random
from itertools import combinations

n = 14

def compute_girth(G):
    if G.number_of_edges() == 0:
        return float('inf')
    try:
        return nx.girth(G)
    except:
        return float('inf')

def is_3_colorable(G):
    try:
        coloring = nx.coloring.greedy_color(G, strategy='largest_first')
        return max(coloring.values()) + 1 <= 3
    except:
        return False

def check_3_colorable_exact(G):
    """Check if graph is 3-colorable using backtracking"""
    n = G.number_of_nodes()
    nodes = list(G.nodes())
    color = {}

    def backtrack(idx):
        if idx == len(nodes):
            return True
        v = nodes[idx]
        neighbor_colors = {color[u] for u in G.neighbors(v) if u in color}
        for c in range(3):
            if c not in neighbor_colors:
                color[v] = c
                if backtrack(idx + 1):
                    return True
                del color[v]
        return False

    return backtrack(0)

# Greedy construction: add edges one by one, maintaining girth >= 7 and 3-colorability
def greedy_build(n, target_edges, seed=42):
    random.seed(seed)
    G = nx.Graph()
    G.add_nodes_from(range(n))

    possible_edges = [(i,j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(possible_edges)

    for u, v in possible_edges:
        G.add_edge(u, v)
        g = compute_girth(G)
        if g < 7:
            G.remove_edge(u, v)
            continue
        if not check_3_colorable_exact(G):
            G.remove_edge(u, v)
            continue
        if G.number_of_edges() >= target_edges:
            break

    return G

# Try multiple seeds
best_G = None
best_edges = 0

for seed in range(100):
    G = greedy_build(n, 19, seed=seed)
    m = G.number_of_edges()
    if m > best_edges:
        best_edges = m
        best_G = G.copy()
        print(f"Seed {seed}: {m} edges, girth={compute_girth(G)}, 3-col={check_3_colorable_exact(G)}")
    if m >= 19:
        print(f"Found solution with seed {seed}!")
        break

print(f"\nBest: {best_edges} edges")

