import networkx as nx
import random
from itertools import combinations

n = 14

def compute_girth(G):
    if G.number_of_edges() == 0:
        return float('inf')
    try:
        return nx.girth(G)
    except:
        return float('inf')

def check_3_colorable_exact(G):
    nodes = list(G.nodes())
    color = {}

    def backtrack(idx):
        if idx == len(nodes):
            return True
        v = nodes[idx]
        neighbor_colors = {color[u] for u in G.neighbors(v) if u in color}
        for c in range(3):
            if c not in neighbor_colors:
                color[v] = c
                if backtrack(idx + 1):
                    return True
                del color[v]
        return False

    return backtrack(0)

def is_valid(G):
    return compute_girth(G) >= 7 and check_3_colorable_exact(G)

# Start with the 17-edge graph and try to add edges
best_edges_list = [(0, 9), (0, 8), (0, 12), (1, 8), (1, 11), (1, 13), (2, 7), (2, 4), 
                   (3, 12), (3, 5), (4, 6), (4, 11), (5, 10), (6, 12), (7, 9), (7, 10), (10, 13)]

G_best = nx.Graph()
G_best.add_nodes_from(range(n))
G_best.add_edges_from(best_edges_list)

# Try all possible additional edges
all_possible = [(i,j) for i in range(n) for j in range(i+1, n)]
current_edges = set(G_best.edges())
non_edges = [(i,j) for i,j in all_possible if (i,j) not in current_edges]

print(f"Current: {G_best.number_of_edges()} edges")
print(f"Non-edges to try: {len(non_edges)}")

# Try adding each non-edge
added = []
for u, v in non_edges:
    G_best.add_edge(u, v)
    if is_valid(G_best):
        added.append((u,v))
        print(f"Added edge ({u},{v}), now {G_best.number_of_edges()} edges")
        if G_best.number_of_edges() >= 19:
            break
    else:
        G_best.remove_edge(u, v)

print(f"\nFinal: {G_best.number_of_edges()} edges")
print("Edges:", sorted(G_best.edges()))
print("Girth:", compute_girth(G_best))
print("3-colorable:", check_3_colorable_exact(G_best))
